package vn.nanase.hako;
import android.content.Context;
import android.util.AtomicFile;
import java.io.*;
import org.json.*;
import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
public final class StoryInfo {
 public static void invalidateDisk(Context c){Store.delete(new File(c.getFilesDir(),"story-info"));}
 public String id="",title="",url="",summary="",status="Chưa rõ",updatedText="Chưa rõ",latestKey="",author="",artist="";public String category="",cover="",rating="",views="",translator="";public JSONArray tags=new JSONArray(),details=new JSONArray(),statistics=new JSONArray();public int chapters;public long updatedAt,fetchedAt;
 public static StoryInfo local(Store.Book book,int count){StoryInfo info=new StoryInfo();info.id=book.id;info.title=book.title;info.url=book.url;info.chapters=count;info.summary="Chưa có giới thiệu đã lưu. Mục lục và tiến trình trên máy vẫn sử dụng được.";return info;}
 public static StoryInfo parse(String html,String url){Document d=Jsoup.parse(html,url);StoryInfo info=new StoryInfo();info.url=HakoParser.storyUrl(url);info.id=HakoParser.storyId(info.url);info.title=HakoParser.title(html,info.url);info.fetchedAt=System.currentTimeMillis();java.util.List<HakoParser.Link> links=HakoParser.chapters(html,info.url);info.chapters=links.size();if(!links.isEmpty()){HakoParser.Link last=links.get(links.size()-1);info.latestKey=last.id+"|"+last.title;}
  Element summary=d.selectFirst(".summary-content, .series-summary, .summary-wrapper .summary");if(summary!=null){StringBuilder paragraphs=new StringBuilder();for(Element part:summary.select("p")){if(paragraphs.length()>0)paragraphs.append("\n\n");paragraphs.append(part.text());}info.summary=paragraphs.length()>0?paragraphs.toString():summary.text().trim();}
  for(Element row:d.select(".series-information .info-item, .series-information-block .info-item, .series-overview .info-item")){String text=row.text(),lower=text.toLowerCase(java.util.Locale.ROOT);Element value=row.selectFirst(".info-value, .value");String content=value==null?text.substring(Math.max(0,text.indexOf(':')+1)).trim():value.text();if(lower.contains("tác giả"))info.author=content;if(lower.contains("họa sĩ")||lower.contains("hoạ sĩ"))info.artist=content;if(lower.contains("tình trạng")||lower.contains("trạng thái")||lower.startsWith("status"))info.status=content;if(lower.contains("cập nhật")||lower.contains("lần cuối")||lower.contains("last update"))info.updatedText=content;}
  for(Element time:d.select(".statistic-item .timeago[datetime], .statistic-item .timeago[title], .series-information time[datetime], .series-information [data-timestamp], .series-information .timeago[title], .series-information-block time[datetime]")){String date=time.hasAttr("datetime")?time.attr("datetime"):time.hasAttr("data-timestamp")?time.attr("data-timestamp"):time.attr("title");long stamp=ShelfPolicy.timestamp(date);if(stamp>info.updatedAt){info.updatedAt=stamp;info.updatedText=time.text().isEmpty()?date:time.text();}}
  info.category=info.id.startsWith("ai-dich-")?"AI dịch":info.id.startsWith("sang-tac-")?"Sáng tác":"Truyện dịch";
  for(Element tag:d.select(".series-gernes a,.series-genres a,.series-tags a"))info.tags.put(tag.text());
  for(Element row:d.select(".series-information .info-item,.series-information-block .info-item"))info.details.put(row.text());
  for(Element row:d.select(".statistic-item"))info.statistics.put(row.text());
  Element cover=d.selectFirst(".series-cover img");if(cover!=null)info.cover=cover.hasAttr("data-src")?cover.absUrl("data-src"):cover.absUrl("src");
  if(info.updatedAt==0)info.updatedAt=ShelfPolicy.timestamp(info.updatedText);return info;
 }
 public static StoryInfo prepared(JSONObject book)throws Exception{StoryInfo i=new StoryInfo();i.id=book.getString("id");i.title=book.getString("title");i.url=HakoParser.sharedUrl(book.getString("url"));i.summary=book.optString("summary");i.author=book.optString("author");i.artist=book.optString("artist");i.status=book.optString("status");i.updatedText=book.optString("updated_text");i.category=book.optString("category",i.id.startsWith("ai-dich-")?"AI dịch":i.id.startsWith("sang-tac-")?"Sáng tác":"Truyện dịch");i.cover=book.optString("cover_asset");i.rating=book.optString("rating");i.views=book.optString("views");i.chapters=book.optInt("chapter_count");i.tags=book.optJSONArray("tags");i.details=book.optJSONArray("details");i.statistics=book.optJSONArray("statistics");i.fetchedAt=System.currentTimeMillis();return i;}
 private static AtomicFile file(Context c,String id){if(!id.matches("[a-z0-9-]+"))throw new IllegalArgumentException();return new AtomicFile(new File(new File(c.getFilesDir(),"story-info"),id+".json"));}
 public void save(Context c)throws Exception{JSONObject j=new JSONObject().put("category",category).put("cover",cover).put("rating",rating).put("views",views).put("tags",tags).put("details",details).put("statistics",statistics).put("id",id).put("author",author).put("artist",artist).put("title",title).put("url",url).put("summary",summary).put("status",status).put("updatedText",updatedText).put("updatedAt",updatedAt).put("chapters",chapters).put("fetchedAt",fetchedAt).put("latestKey",latestKey);AtomicFile f=file(c,id);FileOutputStream stream=null;try{stream=f.startWrite();stream.write(j.toString().getBytes("UTF-8"));f.finishWrite(stream);}catch(Exception e){if(stream!=null)f.failWrite(stream);throw e;}}
 public static StoryInfo load(Context c,String id)throws Exception{JSONObject j=new JSONObject(new String(file(c,id).readFully(),"UTF-8"));StoryInfo i=new StoryInfo();i.id=j.getString("id");if(!id.equals(i.id))throw new IOException("Wrong story");i.category=j.optString("category");i.cover=j.optString("cover");i.rating=j.optString("rating");i.views=j.optString("views");i.tags=j.optJSONArray("tags");i.details=j.optJSONArray("details");i.statistics=j.optJSONArray("statistics");i.author=j.optString("author");i.artist=j.optString("artist");i.title=j.optString("title");i.url=j.optString("url");i.summary=j.optString("summary");i.status=j.optString("status","Chưa rõ");i.updatedText=j.optString("updatedText","Chưa rõ");i.updatedAt=j.optLong("updatedAt");i.chapters=j.optInt("chapters");i.fetchedAt=j.optLong("fetchedAt");i.latestKey=j.optString("latestKey");return i;}
}
